python3 -c "
import os

for rdir in ['extracted/ipsw/ramdisk_erase', 'extracted/ipsw/ramdisk_update']:
    broken = []
    total_links = 0
    for root, dirs, files in os.walk(rdir):
        for f in files + dirs:
            p = os.path.join(root, f)
            if os.path.islink(p):
                total_links += 1
                target = os.readlink(p)
                # check resolution within rdir
                resolved = os.path.normpath(os.path.join(root, target))
                if not os.path.exists(resolved):
                    broken.append((p[len(rdir):], target, resolved[len(rdir):]))
    print(f'{rdir}: total symlinks = {total_links}, broken = {len(broken)}')
    if broken:
        print('  Sample broken (first 5):', broken[:5])
"

